 engine=types.SimpleNamespace(_quality_pools=None,_supply_plan=None,valid_card=lambda *args:True,candidates=lambda:tuple(moments|retired),book=lambda st,s,t:{'rows':[{'spid':s}]},rare_stock=lambda st,t:[{'spid':s} for s in moments|retired]);hc=types.SimpleNamespace(HERE=str(root),market_engine=engine)
